const PAGE_SIZE = 96;
const svgNS = 'http://www.w3.org/2000/svg';
const search = document.querySelector('#sketch-search');
const navigation = document.querySelector('.sketch-index');
const group = document.querySelector('#sketch-group-title');
const grid = document.querySelector('.sketch-grid');
const summary = document.querySelector('#sketch-results');
const pagers = [...document.querySelectorAll('.sketch-pages')];
const feedback = document.querySelector('#sketch-feedback');
const correction = document.querySelector('#sketch-copy-path');
const links = [...navigation.querySelectorAll('a')];
let page = 0;

export function start(icons) {
  const records = icons.map(([name, category, path, source, term, glyph]) => ({
    name, category, path, source, glyph,
    keywords: [name.replaceAll('-', ' '), category, source, term,
      name === 'hand' ? 'open palm raised high five fingers' : ''].join(' '),
  }));
  const displaySources = { shared: 'Shared', tabler: 'Tabler', hugeicons: 'Hugeicons' };

  function card(icon) {
    const figure = document.createElement('figure');
    figure.className = 'sketch-card';
    const svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('viewBox', '-8 -8 116 116');
    svg.setAttribute('aria-hidden', 'true');
    const path = document.createElementNS(svgNS, 'path');
    path.setAttribute('d', icon.path);
    path.setAttribute('filter', 'url(#sketch-wobble)');
    svg.append(path);
    const caption = document.createElement('figcaption');
    const name = document.createElement('code');
    name.textContent = icon.name;
    const source = document.createElement('small');
    source.textContent = displaySources[icon.source];
    const copy = document.createElement('button');
    copy.type = 'button';
    copy.textContent = icon.glyph ? 'Copy glyph' : 'Copy art';
    copy.setAttribute('aria-label', `${copy.textContent} for ${icon.name} (${source.textContent})`);
    copy.addEventListener('click', async () => {
      const value = JSON.stringify(icon.glyph ? { glyph: icon.name } : { art: icon.path });
      correction.hidden = true;
      try {
        await navigator.clipboard.writeText(value);
        feedback.textContent = `Copied ${icon.name}.`;
      } catch {
        correction.hidden = false;
        const field = correction.querySelector('textarea');
        field.value = value;
        field.focus();
        field.select();
      }
    });
    caption.append(name, source);
    figure.append(svg, caption, copy);
    return figure;
  }

  function render() {
    const current = links.find(link => link.hash === location.hash) ?? links[0];
    const category = current.dataset.group;
    const terms = search.value.toLowerCase().trim().split(/[\s-]+/).filter(Boolean);
    const matches = records.filter(icon => (!category || icon.category === category) &&
      terms.every(term => icon.keywords.includes(term)));
    const pages = Math.max(1, Math.ceil(matches.length / PAGE_SIZE));
    page = Math.min(page, pages - 1);
    const offset = page * PAGE_SIZE;
    const showing = matches.slice(offset, offset + PAGE_SIZE);
    group.textContent = current.textContent;
    for (const link of links) {
      if (link === current) link.setAttribute('aria-current', 'location');
      else link.removeAttribute('aria-current');
    }
    grid.replaceChildren(...showing.map(card));
    summary.textContent = showing.length
      ? `${(offset + 1).toLocaleString()}–${(offset + showing.length).toLocaleString()} of ${matches.length.toLocaleString()} icons`
      : 'No icons match this search.';
    for (const pager of pagers) {
      pager.hidden = pages === 1;
      pager.querySelector('[data-step="-1"]').disabled = !page;
      pager.querySelector('[data-step="1"]').disabled = page + 1 >= pages;
    }
  }

  search.disabled = false;
  search.addEventListener('input', () => { page = 0; render(); });
  window.addEventListener('hashchange', () => { page = 0; render(); });
  for (const pager of pagers) {
    for (const button of pager.querySelectorAll('button')) {
      button.addEventListener('click', () => {
        page += Number(button.dataset.step);
        render();
        if (pager === pagers[1]) {
          group.focus({ preventScroll: true });
          group.scrollIntoView({ block: 'start' });
        } else if (button.disabled) {
          pager.querySelector('button:enabled')?.focus();
        }
      });
    }
  }
  render();
}

